    const iqr = rint(3, 40); return { text: `n = ${n}, IQR = ${iqr}. Ширина интервала по формуле Фридмана–Диакониса? (2 знака)`, answer: 2 * iqr / c, sol: `h = 2 · IQR / n^(1/3) = 2 · ${iqr} / ${c} = ${fmt(2 * iqr / c)}` };
