  { t: 'hier', name: 'Евклид, Манхэттен, Чебышёв', f: () => {
    const d = rint(2, 4); const x = Array.from({ length: d }, () => rint(0, 10)), y = Array.from({ length: d }, () => rint(0, 10));
    const diff = x.map((v, i) => Math.abs(v - y[i])); const m = pick(['e', 'm', 'c']);
    const ans = m === 'e' ? Math.sqrt(sum(diff.map(v => v * v))) : m === 'm' ? sum(diff) : Math.max(...diff);
    const nm = { e: 'евклидово', m: 'манхэттенское (cityblock)', c: 'расстояние Чебышёва (max)' }[m];
    const sol = m === 'e' ? `√(${diff.map(v => v + '²').join(' + ')}) = √${sum(diff.map(v => v * v))} = ${fmt(ans)}` : m === 'm' ? `${diff.join(' + ')} = ${ans}` : `max(${diff.join(', ')}) = ${ans}`;
    return { text: `X = (${x.join(', ')}), Y = (${y.join(', ')}). Найди ${nm} расстояние. Округли до 2 знаков.`, answer: ans, sol: `Модули разностей: ${diff.join(', ')}.${F(sol)}` };
  } },
  { t: 'hier', name: 'Расстояние Хэмминга', f: () => {
    const L = rint(6, 8); const digits = Math.random() < .5; const a = Array.from({ length: L }, () => digits ? rint(0, 9) : rint(0, 1));
    const b = a.map(v => Math.random() < .35 ? (digits ? (v + rint(1, 9)) % 10 : 1 - v) : v);
    const pos = a.map((v, i) => v !== b[i] ? i + 1 : 0).filter(Boolean);
    return { text: `D(${a.join('')}, ${b.join('')}) = ? (расстояние Хэмминга)`, answer: pos.length, sol: `Символы различаются в позициях: ${pos.length ? pos.join(', ') : 'нигде'}. Расстояние = ${pos.length}.` };
  } },
  { t: 'hier', name: 'Жаккар и Дайс', f: () => {
    const W = ['анализ', 'данные', 'кластер', 'выборка', 'медиана', 'модель', 'точка', 'расстояние', 'гистограмма', 'плотность', 'дерево', 'центр'];
    const pool = shuffle(W); const common = pool.slice(0, rint(1, 3)); const A = [...common, ...pool.slice(3, 3 + rint(1, 3))]; const B = [...common, ...pool.slice(6, 6 + rint(1, 3))];
    const inter = common.length, uni = A.length + B.length - inter; const m = pick(['j', 'd']);
    const ans = m === 'j' ? inter / uni : 2 * inter / (A.length + B.length);
    return { text: `A = {${A.join(', ')}}<br>B = {${B.join(', ')}}<br>Найди ${m === 'j' ? 'меру Жаккара' : 'меру Сёренсена–Дайса'}. Округли до 2 знаков.`, answer: ans,
      sol: `A∩B = {${common.join(', ')}} → ${inter}; |A| = ${A.length}, |B| = ${B.length}, |A∪B| = ${uni}.${F(m === 'j' ? `J = |A∩B| / |A∪B| = ${inter} / ${uni} = ${fmt(ans)}` : `D = 2·|A∩B| / (|A| + |B|) = ${2 * inter} / ${A.length + B.length} = ${fmt(ans)}`)}` };
  } },
  { t: 'hier', name: 'Расстояние между кластерами', f: () => {
    const A = sorted(distinctInts(rint(2, 3), 0, 12)), B = sorted(distinctInts(rint(2, 3), 16, 32));
    const pairs = []; A.forEach(a => B.forEach(b => pairs.push(Math.abs(a - b))));
    const m = pick(['single', 'complete', 'average', 'centroid']);
    const ans = m === 'single' ? Math.min(...pairs) : m === 'complete' ? Math.max(...pairs) : m === 'average' ? mean(pairs) : Math.abs(mean(A) - mean(B));
    const nm = { single: "single (ближайший сосед)", complete: "complete (дальний сосед)", average: "average (среднее невзвешенное)", centroid: "centroid (между центрами)" }[m];
    const sol = m === 'centroid' ? `центры: ${fmt(mean(A))} и ${fmt(mean(B))} → |${fmt(mean(A))} − ${fmt(mean(B))}| = ${fmt(ans)}` :
      `все попарные расстояния: ${pairs.join(', ')}\n` + (m === 'single' ? `min = ${ans}` : m === 'complete' ? `max = ${ans}` : `среднее = ${sum(pairs)} / ${pairs.length} = ${fmt(ans)}`);
    return { text: `Точки на прямой. Кластер A = ${list(A)}, кластер B = ${list(B)}. Расстояние между кластерами методом <b>${nm}</b>? (2 знака)`, answer: ans, sol: F(sol) };
  } },
  { t: 'kmeans', name: 'Одна итерация k-means', f: () => {
    let pts, c1, c2;
    do { pts = sorted(distinctInts(rint(6, 7), 0, 30)); c1 = rint(0, 12); c2 = rint(16, 30); }
    while (!pts.some(p => Math.abs(p - c1) < Math.abs(p - c2)) || !pts.some(p => Math.abs(p - c2) < Math.abs(p - c1)) || pts.some(p => Math.abs(p - c1) === Math.abs(p - c2)));
    const g1 = pts.filter(p => Math.abs(p - c1) < Math.abs(p - c2)), g2 = pts.filter(p => Math.abs(p - c2) < Math.abs(p - c1));
    const which = pick([1, 2]); const ans = which === 1 ? mean(g1) : mean(g2);
    return { text: `Точки на прямой: ${list(pts)}. Начальные центры c₁ = ${c1}, c₂ = ${c2}. Где окажется c${which === 1 ? '₁' : '₂'} после одной итерации? (2 знака)`, answer: ans,
      sol: `Правило 1 — к ближайшему центру: к c₁ ушли ${list(g1)}, к c₂ — ${list(g2)}.<br>Правило 2 — центр в среднее:${F(`c₁ = ${sum(g1)} / ${g1.length} = ${fmt(mean(g1))}\nc₂ = ${sum(g2)} / ${g2.length} = ${fmt(mean(g2))}`)}` };
  } },
  { t: 'kmeans', name: 'Inertia кластера', f: () => {
    const pts = Array.from({ length: rint(3, 5) }, () => rint(0, 12)); const c = mean(pts); const ss = sum(pts.map(p => (p - c) ** 2));
    return { text: `В кластере точки ${list(pts)} (на прямой). Центр — их среднее. Чему равен вклад кластера в <code>inertia_</code>? (2 знака)`, answer: ss,
      sol: `центр = ${fmt(c)}${F(pts.map(p => `(${p} − ${fmt(c)})²`).join(' + ') + ` = ${fmt(ss)}`)}` };
  } },
  { t: 'dbscan', name: 'Силуэт точки', f: () => {
    const A = sorted(distinctInts(3, 0, 10)), B = sorted(distinctInts(3, 12, 30)); const x = pick(A); const others = A.filter(v => v !== x);
    const a = mean(others.map(v => Math.abs(v - x))), b = mean(B.map(v => Math.abs(v - x))); const s = (b - a) / Math.max(a, b);
    return { text: `Кластер 1 = ${list(A)}, кластер 2 = ${list(B)} (точки на прямой). Найди силуэт точки ${x}. Округли до 2 знаков.`, answer: s,
      sol: F(`a = среднее до своих: (${others.map(v => Math.abs(v - x)).join(' + ')}) / ${others.length} = ${fmt(a)}\nb = среднее до кластера 2: (${B.map(v => Math.abs(v - x)).join(' + ')}) / 3 = ${fmt(b)}\ns = (b − a) / max(a, b) = (${fmt(b)} − ${fmt(a)}) / ${fmt(Math.max(a, b))} = ${fmt(s)}`) };
  } },
  { t: 'dbscan', name: 'Тип точки в DBSCAN', f: () => {
    for (let tries = 0; tries < 200; tries++) {
      const pts = sorted(distinctInts(rint(8, 10), 0, 30)); const eps = pick([1, 2, 2, 3]), m = pick([2, 3, 3, 4]);
      const nb = p => pts.filter(q => Math.abs(q - p) <= eps);
      const core = new Set(pts.filter(p => nb(p).length >= m));
      const type = p => core.has(p) ? 0 : nb(p).some(q => core.has(q)) ? 1 : 2;
      const want = rint(0, 2); const cand = pts.filter(p => type(p) === want); if (!cand.length) continue;
      const p = pick(cand); const N = nb(p);
      const names = ['корневая', 'граничная', 'выброс'];
      const why = [`в её окрестности ${N.length} ≥ m = ${m} точек`, `в её окрестности ${N.length} < ${m}, но сосед ${N.filter(q => core.has(q)).join(', ')} — корневой`, `в окрестности ${N.length} < ${m} и нет корневых соседей → метка −1`][want];
      return { text: `Точки на прямой: ${list(pts)}.<br><code>DBSCAN(eps=${eps}, min_samples=${m})</code> — сама точка входит в подсчёт, соседи на расстоянии ≤ eps. Какого типа точка <b>${p}</b>?`, type: 'choice', options: names, answer: want,
        sol: `ε-окрестность точки ${p}: ${list(N)}. Она ${names[want]}: ${why}.<br>Корневые точки во всей выборке: ${core.size ? list([...core]) : 'нет'}.` };
    }
  } },
  { t: 'dbscan', name: 'Сколько корневых точек', f: () => {
    const pts = sorted(distinctInts(rint(8, 10), 0, 25)); const eps = pick([1, 2, 3]), m = pick([3, 3, 4]);
    const cnt = pts.map(p => pts.filter(q => Math.abs(q - p) <= eps).length); const core = pts.filter((p, i) => cnt[i] >= m);
    return { text: `Точки: ${list(pts)}. eps = ${eps}, min_samples = ${m} (точка считает и себя). Сколько корневых точек?`, answer: core.length,
      sol: `Число точек в окрестности: ${pts.map((p, i) => `${p}→${cnt[i]}`).join(', ')}.<br>Корневые (≥ ${m}): ${core.length ? list(core) : 'нет'} — всего ${core.length}.` };
  } }
